// `time` builds friendly durations ("half a minute", "3 minutes"...) per language.

function plural3(n, one, few, many) { // ru / uk style plurals
    const a = n % 10, b = n % 100;
    if (a === 1 && b !== 11) return one;
    if (a >= 2 && a <= 4 && (b < 12 || b > 14)) return few;
    return many;
}

